   entirely — so the warning was advice any client could decline to render. */
describe('delete guards live references', () => {
  const referencing = () =>
    makeLibrary({
      moves: [{ Id: 'm-1', Name: 'Take a Risk', Kind: 'Basic', VirtueId: 'v-might', Description: '', Results: {} }] as any,
