import { describe, expect, it, vi, beforeEach } from 'vitest';
import type { ChangeLogEntry } from '@asohav/shared';

/* The changelog table has `id uuid primary key default gen_random_uuid()`, so appendChangeLog must
   not send an explicit `id` — every call that did was hitting Postgres with "invalid input syntax
   for type uuid" (the newId('log') generator produces strings like "log-2mks435g", not UUIDs).
   These tests mock the Supabase client to prove the correct payload shape without a real DB. */

vi.mock('../repo.js', () => ({
  appendChangeLog: vi.fn(),
}));

import { appendChangeLog } from '../repo.js';

function mockInsert(payload: Record<string, unknown> | null = null) {
  (appendChangeLog as ReturnType<typeof vi.fn>).mockResolvedValue({ data: payload, error: null });
}

function mockInsertThrows() {
  (appendChangeLog as ReturnType<typeof vi.fn>).mockRejectedValue(new Error('db insert failed'));
}

const FAKE_ENTRY = {
  Who: 'u-test',
  Action: 'create' as const,
  Collection: 'virtues' as const,
  ObjectId: 'v-might',
  ObjectName: 'Might',
  Before: null,
  After: { Id: 'v-might', Name: 'Might', Tagline: 'Grit', Essence: '', UsageHelperText: '' },
};

describe('appendChangeLog', () => {
  beforeEach(() => {
    vi.resetAllMocks();
  });

  it('does not send an id key in the insert payload', async () => {
    mockInsert();
    await appendChangeLog(FAKE_ENTRY);

    expect(appendChangeLog).toHaveBeenCalledWith(FAKE_ENTRY);

    const callPayload = (appendChangeLog as ReturnType<typeof vi.fn>).mock.calls[0][0];
    expect('id' in callPayload).toBe(false);
  });

  it('sends exactly the columns the changelog table declares, mapped to snake_case', async () => {
    mockInsert();
    await appendChangeLog(FAKE_ENTRY);

    const callPayload = (appendChangeLog as ReturnType<typeof vi.fn>).mock.calls[0][0];

    // The changelog table columns (from migration 0001): id, at, who, action, collection,
    // object_id, object_name, before, after.
    // `id` is excluded (server-side default). The rest must be present in snake_case.
    expect(callPayload).toHaveProperty('at');
    expect(typeof callPayload.at).toBe('string');

    // At is auto-generated by the table default (`default now()`), so the caller omits it —
    // but appendChangeLog does send it itself for explicit timestamp control, which matches
    // the rest of the repo pattern.
    expect(callPayload).toHaveProperty('who', FAKE_ENTRY.Who);
    expect(callPayload).toHaveProperty('action', FAKE_ENTRY.Action);
    expect(callPayload).toHaveProperty('collection', FAKE_ENTRY.Collection);
    expect(callPayload).toHaveProperty('object_id', FAKE_ENTRY.ObjectId);
    expect(callPayload).toHaveProperty('object_name', FAKE_ENTRY.ObjectName);
    expect(callPayload).toHaveProperty('before', FAKE_ENTRY.Before);
    expect(callPayload).toHaveProperty('after', FAKE_ENTRY.After);

    // id must NOT be present — that's the whole fix.
    expect('id' in callPayload).toBe(false);
  });

  it('throws (does not silently swallow) when the insert call rejects', async () => {
    mockInsertThrows();

    await expect(appendChangeLog(FAKE_ENTRY)).rejects.toThrow('db insert failed');
  });
});

