import { beforeEach, describe, expect, it, vi } from 'vitest';

/* The changelog table has `id uuid primary key default gen_random_uuid()`, so appendChangeLog must
   not send an explicit `id` — every call that did was hitting Postgres with "invalid input syntax"
   for type uuid (newId('log') produces strings like "log-2mks435g", not UUIDs).
   These tests verify the correct insert payload shape without a real database. */

const FAKE_ENTRY = {
  Who: 'u-test',
  Action: 'create' as const,
  Collection: 'virtues' as const,
  ObjectId: 'v-might',
  ObjectName: 'Might',
  Before: null,
  After: { Id: 'v-might', Name: 'Might', Tagline: 'Grit', Essence: '', UsageHelperText: '' },
};

// Build a fresh mock Supabase chain, reset each test.
let insertFn: ReturnType<typeof vi.fn>;
let selectFn: ReturnType<typeof vi.fn>;

function buildMockChain() {
  insertFn = vi.fn().mockResolvedValue({ data: null, error: null });
  selectFn = vi.fn();
  return {
    from: vi.fn((table: string) => {
      if (table === 'changelog') {
        return { insert: insertFn, select: selectFn };
      }
      return { insert: vi.fn().mockResolvedValue({ data: null, error: null }), select: selectFn };
    }),
  };
}

describe('appendChangeLog', () => {
  let repo: typeof import('../repo.js');
  let supabase: typeof import('../supabase.js');

  beforeEach(async () => {
    vi.resetAllMocks();
    const mock = buildMockChain();
    vi.doMock('../supabase.js', () => ({ supabaseAdmin: mock }));
    repo = await vi.doImport('../repo.js');
    supabase = await vi.doImport('../supabase.js');
  });

  it('does not send an id key in the insert payload', async () => {
    insertFn.mockResolvedValue({ data: null, error: null });

    await repo.appendChangeLog(FAKE_ENTRY);

    const callArgs = insertFn.mock.calls[0]!;
    expect(callArgs.length).toBe(1);
    expect('id' in callArgs[0]).toBe(false);
  });

  it('sends exactly the columns the changelog table declares, mapped to snake_case', async () => {
    insertFn.mockResolvedValue({ data: null, error: null });

    await repo.appendChangeLog(FAKE_ENTRY);

    const callArgs = insertFn.mock.calls[0]!;
    expect(callArgs.length).toBe(1);
    const payload: Record<string, unknown> = callArgs[0];

    // The changelog table columns (from migration 0001_init.sql): id, at, who, action,
    // collection, object_id, object_name, before, after.
    // `id` is excluded because the table has `default gen_random_uuid()`.
    expect('at' in payload).toBe(true);
    expect(typeof payload.at).toBe('string');

    expect(payload).toHaveProperty('who', FAKE_ENTRY.Who);
    expect(payload).toHaveProperty('action', FAKE_ENTRY.Action);
    expect(payload).toHaveProperty('collection', FAKE_ENTRY.Collection);
    expect(payload).toHaveProperty('object_id', FAKE_ENTRY.ObjectId);
    expect(payload).toHaveProperty('object_name', FAKE_ENTRY.ObjectName);
    expect(payload).toHaveProperty('before', FAKE_ENTRY.Before);
    expect(payload).toHaveProperty('after', FAKE_ENTRY.After);

    // Main invariant: id must NOT be present — that's the entire fix.
    expect('id' in payload).toBe(false);

    // Verify the target table name.
    expect(supabase.supabaseAdmin.from).toHaveBeenCalledWith('changelog');
  });

  it('throws (does not silently swallow) when the insert call rejects', async () => {
    insertFn.mockRejectedValue(new Error('db insert failed'));

    await expect(repo.appendChangeLog(FAKE_ENTRY)).rejects.toThrow('db insert failed');
  });
});
